package edu.pe.cibertec.saibm.inventario.infrastructure.config; import java.time.Instant; import org.springframework.transaction.annotation.Transactional; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.usecase.InventoryService; public class InventoryTransactionalFacade implements InventoryUseCase {private final InventoryService service; InventoryTransactionalFacade(InventoryService s){service=s;} @Transactional public Outcome hold(String b,int q,Instant e,String k,String c){return service.hold(b,q,e,k,c);}@Transactional public Outcome commit(String b,String k,String c){return service.commit(b,k,c);}@Transactional public Outcome release(String b,String k,String c){return service.release(b,k,c);}}
